begin;

do $seed$
declare
  owner_id uuid;
  item jsonb;
  question_id uuid;
  inserted_count integer := 0;
begin
  select id into owner_id from public.profiles where role = 'admin' and disabled_at is null order by created_at,id limit 1;
  if owner_id is null then raise exception 'Un administrateur actif doit être créé avant la banque initiale.'; end if;
  for item in select value from jsonb_array_elements($bank$[{"chapterId":"cellulaire","difficulty":"easy","prompt":"Quel compartiment d’une cellule eucaryote contient généralement la majorité de son ADN ?","options":["Le noyau","L’appareil de Golgi","Le lysosome","La membrane plasmique"],"correctAnswers":[0],"explanation":"Le noyau renferme les chromosomes nucléaires. Les mitochondries, et les chloroplastes chez les végétaux, possèdent également un génome propre.","image":null,"status":"published"},{"chapterId":"cellulaire","difficulty":"easy","prompt":"Quelles structures sont présentes dans une cellule végétale chlorophyllienne typique ?","options":["Une membrane plasmique","Une paroi pectocellulosique","Des chloroplastes","Une paroi de peptidoglycane"],"correctAnswers":[0,1,2],"explanation":"La cellule végétale possède une membrane plasmique entourée d’une paroi pectocellulosique. Dans les tissus chlorophylliens, les chloroplastes assurent la photosynthèse ; le peptidoglycane caractérise les parois bactériennes.","image":"/illustrations/cell.svg","status":"published"},{"chapterId":"cellulaire","difficulty":"medium","prompt":"Lors de la réplication de l’ADN, pourquoi parle-t-on de mécanisme semi-conservatif ?","options":["Chaque molécule fille conserve un brin parental","Une seule des deux molécules filles est conservée","La moitié des nucléotides est détruite","Les deux brins parentaux restent toujours associés"],"correctAnswers":[0],"explanation":"Chaque molécule d’ADN fille associe un brin parental à un brin nouvellement synthétisé. La complémentarité des bases permet de recopier l’information portée par le brin matrice.","image":null,"status":"published"},{"chapterId":"cellulaire","difficulty":"medium","prompt":"Quelles affirmations décrivent correctement la transcription chez les eucaryotes ?","options":["L’ARN polymérase synthétise l’ARN dans le sens 5′ vers 3′","Les deux brins d’un même gène sont simultanément copiés pour produire le même ARN","Le brin matrice est lu dans le sens 3′ vers 5′","La transcription produit directement une protéine"],"correctAnswers":[0,2],"explanation":"L’ARN polymérase allonge l’ARN à son extrémité 3′ en lisant un brin matrice d’ADN. La traduction est une étape distincte au cours de laquelle les ribosomes synthétisent une chaîne polypeptidique.","image":null,"status":"published"},{"chapterId":"cellulaire","difficulty":"easy","prompt":"Quelle est la fonction principale des ribosomes ?","options":["Synthétiser les protéines","Répliquer les chromosomes","Dégrader uniquement les lipides","Stocker le calcium de façon exclusive"],"correctAnswers":[0],"explanation":"Les ribosomes traduisent la séquence d’un ARN messager en une succession d’acides aminés. Les ARN de transfert apportent les acides aminés correspondant aux codons lus.","image":null,"status":"published"},{"chapterId":"cellulaire","difficulty":"hard","prompt":"Chez un organisme diploïde à 2n = 8, combien de chromosomes et de chromatides une cellule possède-t-elle en métaphase de mitose ?","options":["8 chromosomes et 16 chromatides","16 chromosomes et 16 chromatides","4 chromosomes et 8 chromatides","8 chromosomes et 8 chromatides"],"correctAnswers":[0],"explanation":"Après la phase S, chaque chromosome est constitué de deux chromatides sœurs. Le nombre de chromosomes, compté par les centromères non séparés, reste égal à 8 jusqu’à l’anaphase.","image":null,"status":"published"},{"chapterId":"cellulaire","difficulty":"medium","prompt":"Quels événements peuvent produire un brassage génétique lors d’une méiose normale ?","options":["Les crossing-over entre chromatides de chromosomes homologues","La répartition indépendante des paires de chromosomes homologues","La duplication identique des centrosomes","La traduction des ARN messagers"],"correctAnswers":[0,1],"explanation":"Les crossing-over de prophase I réalisent un brassage intrachromosomique. La répartition des homologues à la première division produit un brassage interchromosomique.","image":null,"status":"published"},{"chapterId":"cellulaire","difficulty":"hard","prompt":"Un individu de génotype AaBb produit des gamètes. Si les deux gènes s’assortissent indépendamment, quelle distribution est attendue ?","options":["AB, Ab, aB et ab à 25 % chacun","AB et ab à 50 % chacun uniquement","Aa et Bb à 50 % chacun","AABB dans tous les gamètes"],"correctAnswers":[0],"explanation":"L’assortiment indépendant donne quatre types de gamètes équiprobables en l’absence de biais de ségrégation. Chaque gamète reçoit un seul allèle de chacun des deux gènes.","image":null,"status":"published"},{"chapterId":"cellulaire","difficulty":"medium","prompt":"Quel gradient fournit directement l’énergie à l’ATP synthase mitochondriale ?","options":["Un gradient électrochimique de protons à travers la membrane interne","Un gradient de glucose à travers la membrane externe","Un gradient d’ADN dans la matrice","Un gradient de dioxygène à travers l’enveloppe nucléaire"],"correctAnswers":[0],"explanation":"La chaîne respiratoire contribue à accumuler les protons dans l’espace intermembranaire. Leur retour vers la matrice par l’ATP synthase couple le gradient électrochimique à la synthèse d’ATP.","image":null,"status":"published"},{"chapterId":"cellulaire","difficulty":"hard","prompt":"Une mutation ponctuelle synonyme dans une séquence codante implique nécessairement que…","options":["Le codon modifié code le même acide aminé","La protéine est toujours produite en même quantité","L’épissage ne peut jamais être affecté","La mutation améliore la valeur sélective"],"correctAnswers":[0],"explanation":"Une substitution synonyme conserve l’acide aminé spécifié par le codon. Elle peut néanmoins influencer l’épissage, la stabilité de l’ARN ou l’efficacité de sa traduction.","image":null,"status":"published"},{"chapterId":"vegetale","difficulty":"easy","prompt":"Dans quel organite se déroule la photosynthèse d’une cellule de feuille chlorophyllienne ?","options":["Le chloroplaste","Le lysosome","Le centrosome","L’appareil de Golgi"],"correctAnswers":[0],"explanation":"Les chloroplastes renferment les pigments et les systèmes enzymatiques nécessaires à la photosynthèse. Les réactions photochimiques ont lieu dans les membranes des thylakoïdes, tandis que le cycle de Calvin se déroule dans le stroma.","image":null,"status":"published"},{"chapterId":"vegetale","difficulty":"easy","prompt":"Quel tissu assure principalement le transport de l’eau et des ions minéraux des racines vers les feuilles ?","options":["Le xylème","Le phloème","L’épiderme","Le méristème apical"],"correctAnswers":[0],"explanation":"Le xylème conduit la sève brute dans des éléments conducteurs généralement morts à maturité. Le phloème transporte notamment des assimilats organiques entre organes sources et organes puits.","image":null,"status":"published"},{"chapterId":"vegetale","difficulty":"medium","prompt":"Quelles fonctions sont associées aux stomates ?","options":["Permettre des échanges de CO₂","Participer à la régulation de la transpiration","Transporter directement la sève élaborée","Produire les grains de pollen"],"correctAnswers":[0,1],"explanation":"L’ouverture stomatique facilite l’entrée du CO₂ nécessaire à la photosynthèse et la sortie de vapeur d’eau. Les cellules de garde modulent cette ouverture, réalisant un compromis entre acquisition de carbone et économie d’eau.","image":"/illustrations/leaf.svg","status":"published"},{"chapterId":"vegetale","difficulty":"medium","prompt":"Quelle est l’origine du dioxygène libéré par la photosynthèse oxygénique ?","options":["L’oxydation de l’eau au photosystème II","La décarboxylation du glucose","La réduction du CO₂ dans le stroma","La dissociation spontanée de l’ATP"],"correctAnswers":[0],"explanation":"Le complexe d’oxydation de l’eau associé au photosystème II prélève des électrons à l’eau et libère du dioxygène. Le CO₂ fournit le carbone incorporé dans la matière organique.","image":null,"status":"published"},{"chapterId":"vegetale","difficulty":"hard","prompt":"Dans le cycle de Calvin, quelles molécules issues des réactions photochimiques sont consommées ?","options":["L’ATP","Le NADPH","Le dioxygène comme substrat obligatoire de la Rubisco","Le peptidoglycane"],"correctAnswers":[0,1],"explanation":"Le cycle de Calvin utilise de l’ATP et du pouvoir réducteur sous forme de NADPH pour assimiler le carbone. La Rubisco peut aussi fixer l’oxygène, mais cette activité initie la photorespiration et ne correspond pas à la carboxylation recherchée.","image":null,"status":"published"},{"chapterId":"vegetale","difficulty":"medium","prompt":"Comment décrit-on habituellement la double fécondation des Angiospermes ?","options":["Un gamète mâle féconde l’oosphère et un autre s’unit à la cellule centrale","Deux gamètes mâles fécondent simultanément la même oosphère","Deux ovules fusionnent","Le pollen se transforme directement en embryon sans fusion de gamètes"],"correctAnswers":[0],"explanation":"Une fusion forme le zygote à l’origine de l’embryon. L’autre donne naissance à l’albumen, généralement triploïde dans le cas classique d’un sac embryonnaire à deux noyaux polaires.","image":null,"status":"published"},{"chapterId":"vegetale","difficulty":"easy","prompt":"Quelle structure est un lieu de croissance primaire d’une tige ?","options":["Le méristème apical caulinaire","Un vaisseau de xylème mort","La cuticule seule","Le grain d’amidon"],"correctAnswers":[0],"explanation":"Les divisions des cellules du méristème apical produisent les cellules à l’origine des tissus primaires. Leur élongation et leur différenciation participent ensuite à la croissance de l’organe.","image":null,"status":"published"},{"chapterId":"vegetale","difficulty":"hard","prompt":"Quelles propositions décrivent correctement le transport dans le phloème ?","options":["Il relie des organes sources à des organes puits","Il peut transporter du saccharose","Il s’effectue exclusivement des racines vers les feuilles","Il nécessite des tubes criblés fonctionnels vivants"],"correctAnswers":[0,1,3],"explanation":"Le transport phloémien distribue les assimilats des sources vers les puits selon l’état physiologique de la plante. Les éléments de tubes criblés des Angiospermes restent vivants et sont associés à des cellules compagnes.","image":null,"status":"published"},{"chapterId":"vegetale","difficulty":"medium","prompt":"En situation de déficit hydrique, quel effet l’acide abscissique favorise-t-il généralement ?","options":["La fermeture des stomates","L’ouverture permanente de tous les stomates","La destruction immédiate du xylème","La disparition de la cuticule"],"correctAnswers":[0],"explanation":"L’acide abscissique participe à la réponse au déficit hydrique en favorisant la fermeture stomatique. La réduction des pertes d’eau s’accompagne souvent d’une diminution de l’entrée de CO₂.","image":null,"status":"published"},{"chapterId":"vegetale","difficulty":"hard","prompt":"Dans une mycorhize mutualiste, quels échanges sont typiquement observés ?","options":["Le champignon reçoit des composés carbonés de la plante","La plante bénéficie d’une meilleure acquisition de certains nutriments minéraux","Le champignon fournit systématiquement tout le CO₂ assimilé par la plante","La plante devient toujours indépendante de la lumière"],"correctAnswers":[0,1],"explanation":"Le réseau mycélien explore un volume de sol qui peut dépasser celui directement accessible aux racines. En contrepartie de nutriments, notamment phosphatés, et parfois d’eau, la plante fournit des ressources carbonées au partenaire fongique.","image":null,"status":"published"},{"chapterId":"physiologie","difficulty":"easy","prompt":"Chez un mammifère, quel organe propulse le sang dans les circulations pulmonaire et systémique ?","options":["Le cœur","Le foie","La rate","Le pancréas"],"correctAnswers":[0],"explanation":"Le cœur droit alimente la circulation pulmonaire et le cœur gauche la circulation systémique. Les valves contribuent à imposer le sens de circulation du sang.","image":null,"status":"published"},{"chapterId":"physiologie","difficulty":"medium","prompt":"Quels facteurs favorisent la diffusion d’un gaz à travers une surface d’échange, toutes choses égales par ailleurs ?","options":["Une plus grande surface","Une plus faible épaisseur","Un gradient de pression partielle plus élevé","Une membrane plus épaisse"],"correctAnswers":[0,1,2],"explanation":"La loi de Fick relie le flux diffusif à la surface et au gradient, et inversement à la distance de diffusion. Les surfaces respiratoires associent donc souvent une grande étendue à une faible épaisseur.","image":null,"status":"published"},{"chapterId":"physiologie","difficulty":"medium","prompt":"Pendant la phase ascendante d’un potentiel d’action classique d’un axone de mammifère, quel flux domine ?","options":["Une entrée de Na⁺ par des canaux voltage-dépendants","Une sortie de Na⁺ par des canaux voltage-dépendants","Une entrée massive de protéines","Une sortie de glucose par exocytose"],"correctAnswers":[0],"explanation":"L’ouverture des canaux sodiques voltage-dépendants augmente rapidement la conductance au sodium. Le gradient électrochimique entraîne une entrée de Na⁺ qui dépolarise la membrane.","image":null,"status":"published"},{"chapterId":"physiologie","difficulty":"hard","prompt":"Quel mécanisme explique principalement la période réfractaire absolue après le déclenchement d’un potentiel d’action ?","options":["L’inactivation transitoire des canaux sodiques voltage-dépendants","La disparition définitive du gradient de sodium","L’absence totale d’ATP dans l’axone","La destruction des canaux potassiques"],"correctAnswers":[0],"explanation":"Les canaux sodiques inactivés ne peuvent pas se rouvrir immédiatement sous l’effet d’une nouvelle dépolarisation. Leur retour à un état activable nécessite une repolarisation suffisante de la membrane.","image":null,"status":"published"},{"chapterId":"physiologie","difficulty":"easy","prompt":"Après un repas glucidique chez un sujet sain, quelle hormone favorise notamment la diminution de la glycémie ?","options":["L’insuline","Le glucagon","L’adrénaline dans sa réponse de stress","La mélatonine comme régulateur principal"],"correctAnswers":[0],"explanation":"L’insuline sécrétée par les cellules β du pancréas favorise le stockage et l’utilisation des nutriments. Elle contribue notamment à la captation du glucose dans certains tissus et à la synthèse de glycogène.","image":null,"status":"published"},{"chapterId":"physiologie","difficulty":"medium","prompt":"Quelles affirmations sur l’hémoglobine adulte sont exactes ?","options":["Elle peut lier réversiblement le dioxygène","Sa saturation dépend de la pression partielle de dioxygène","Elle est localisée principalement dans le plasma chez l’humain sain","Elle possède quatre sous-unités globiniques"],"correctAnswers":[0,1,3],"explanation":"L’hémoglobine des hématies transporte le dioxygène grâce à ses groupements hème. Les interactions entre ses quatre sous-unités permettent une fixation coopérative.","image":null,"status":"published"},{"chapterId":"physiologie","difficulty":"hard","prompt":"À propos de la filtration glomérulaire rénale normale, quelles propositions sont exactes ?","options":["L’eau et de petits solutés peuvent entrer dans le filtrat","Les cellules sanguines sont normalement retenues","La majorité des protéines plasmatiques traverse librement","La barrière de filtration présente une sélectivité de taille et de charge"],"correctAnswers":[0,1,3],"explanation":"La barrière glomérulaire laisse filtrer l’eau et de nombreux petits solutés tout en retenant les cellules et l’essentiel des protéines plasmatiques. Le filtrat est ensuite modifié par réabsorption et sécrétion dans le tubule rénal.","image":null,"status":"published"},{"chapterId":"physiologie","difficulty":"medium","prompt":"Quel événement déclenche habituellement la libération d’un neurotransmetteur dans une synapse chimique ?","options":["L’entrée de Ca²⁺ dans la terminaison présynaptique","L’entrée de chromosomes dans la fente synaptique","La sortie d’ADN du noyau postsynaptique","La fermeture irréversible de tous les canaux ioniques"],"correctAnswers":[0],"explanation":"L’arrivée du potentiel d’action ouvre des canaux calciques voltage-dépendants présynaptiques. L’augmentation locale du calcium favorise la fusion des vésicules et l’exocytose du neurotransmetteur.","image":null,"status":"published"},{"chapterId":"physiologie","difficulty":"hard","prompt":"Lors de la contraction d’un sarcomère strié squelettique, quelles modifications sont attendues ?","options":["Les lignes Z se rapprochent","La bande A conserve approximativement sa longueur","Les filaments d’actine raccourcissent fortement","Le chevauchement actine-myosine augmente"],"correctAnswers":[0,1,3],"explanation":"La contraction repose sur le glissement relatif des filaments, sans raccourcissement de ces derniers. La bande A correspond à la longueur des filaments épais, tandis que les bandes I et la zone H diminuent.","image":null,"status":"published"},{"chapterId":"physiologie","difficulty":"easy","prompt":"Quel exemple illustre une rétroaction négative ?","options":["Une hausse de température déclenche des réponses favorisant sa diminution","Une réponse amplifie toujours la perturbation initiale","Une hormone stimule sans limite sa propre production","Un effecteur ne reçoit jamais de signal"],"correctAnswers":[0],"explanation":"Une rétroaction négative réduit l’écart à une valeur ou une plage régulée. Elle contribue à la stabilité de nombreuses variables physiologiques malgré les perturbations.","image":null,"status":"published"},{"chapterId":"geologie","difficulty":"easy","prompt":"De quoi la lithosphère terrestre est-elle constituée ?","options":["De la croûte et de la partie supérieure rigide du manteau","De la croûte uniquement","Du noyau externe et du noyau interne","De toute la croûte et de tout le manteau"],"correctAnswers":[0],"explanation":"La lithosphère est définie par son comportement mécanique rigide et comprend croûte et manteau lithosphérique. Elle repose sur une asthénosphère dont le comportement à long terme est plus ductile.","image":null,"status":"published"},{"chapterId":"geologie","difficulty":"medium","prompt":"Quelles caractéristiques sont habituellement associées à une dorsale océanique active ?","options":["Une divergence de plaques","Une production de lithosphère océanique","Un magmatisme principalement basaltique","Une disparition systématique de toute activité hydrothermale"],"correctAnswers":[0,1,2],"explanation":"À la dorsale, la remontée du manteau favorise sa fusion partielle par décompression. Les magmas produits participent à la construction de la croûte océanique, dans un contexte souvent hydrothermal.","image":null,"status":"published"},{"chapterId":"geologie","difficulty":"easy","prompt":"Quel mouvement caractérise une zone de subduction ?","options":["Une lithosphère plonge sous une autre plaque","Deux plaques s’écartent sans convergence","Le noyau traverse la croûte","Une plaque disparaît par évaporation"],"correctAnswers":[0],"explanation":"La subduction correspond à l’enfoncement d’une lithosphère dans le manteau au niveau d’une limite convergente. Elle s’accompagne de séismes dont la répartition dessine la plaque plongeante.","image":"/illustrations/subduction.svg","status":"published"},{"chapterId":"geologie","difficulty":"medium","prompt":"Pourquoi les ondes sismiques S ne se propagent-elles pas dans le noyau externe ?","options":["Le noyau externe est liquide et ne soutient pas le cisaillement","Le noyau externe est trop froid","Les ondes S sont des ondes lumineuses","Le noyau externe ne contient aucune matière"],"correctAnswers":[0],"explanation":"Les ondes S sont des ondes de cisaillement, qui nécessitent une rigidité au cisaillement non nulle. Leur absence dans le noyau externe contribue à établir son état liquide.","image":null,"status":"published"},{"chapterId":"geologie","difficulty":"hard","prompt":"Lors de son éloignement d’une dorsale, comment évolue généralement une lithosphère océanique ?","options":["Elle se refroidit","Son épaisseur thermique augmente","Sa densité moyenne tend à augmenter","Sa croûte basaltique s’épaissit continuellement par simple refroidissement"],"correctAnswers":[0,1,2],"explanation":"Le refroidissement augmente l’épaisseur du manteau lithosphérique et entraîne une contraction thermique. L’épaississement de la lithosphère ne doit pas être confondu avec celui de la croûte océanique.","image":null,"status":"published"},{"chapterId":"geologie","difficulty":"medium","prompt":"Que caractérise une texture grenue dans une roche magmatique ?","options":["Des cristaux jointifs généralement visibles à l’œil nu","Une matière entièrement vitreuse sans cristaux","Une stratification sédimentaire obligatoire","Une absence totale de refroidissement"],"correctAnswers":[0],"explanation":"Une texture grenue témoigne généralement d’une cristallisation relativement lente en profondeur. Une texture microlitique est au contraire souvent associée à un refroidissement plus rapide en contexte volcanique.","image":null,"status":"published"},{"chapterId":"geologie","difficulty":"hard","prompt":"Dans une série sédimentaire non renversée, que permet le principe de superposition ?","options":["Une couche est plus récente que celle qu’elle recouvre","Toute roche en contact a exactement le même âge","La couche du sommet est nécessairement la plus ancienne","On obtient directement un âge numérique en millions d’années"],"correctAnswers":[0],"explanation":"Le principe de superposition établit une chronologie relative des dépôts. Il suppose de prendre en compte les déformations, les renversements et les éventuelles discontinuités de la série.","image":null,"status":"published"},{"chapterId":"geologie","difficulty":"hard","prompt":"Quels phénomènes favorisent la fusion partielle du manteau dans des contextes géodynamiques différents ?","options":["Une décompression suffisamment rapide du manteau ascendant","Un apport d’eau abaissant le solidus de la péridotite","Une baisse de température à pression constante dans tous les cas","Une augmentation de pression sans autre modification dans tous les cas"],"correctAnswers":[0,1],"explanation":"Aux dorsales, le manteau ascendant peut franchir son solidus par décompression. Au-dessus d’une plaque en subduction, des fluides libérés par celle-ci favorisent la fusion du manteau sus-jacent.","image":null,"status":"published"},{"chapterId":"geologie","difficulty":"medium","prompt":"Quelles propositions décrivent le métamorphisme ?","options":["Une transformation minéralogique à l’état essentiellement solide","Une réponse à de nouvelles conditions de pression et de température","Une fusion nécessairement totale de la roche","Une transformation possible avec intervention de fluides"],"correctAnswers":[0,1,3],"explanation":"Le métamorphisme modifie les assemblages minéralogiques et souvent les textures sans nécessiter une fusion totale. Les fluides peuvent faciliter les réactions et les transferts de matière.","image":null,"status":"published"},{"chapterId":"geologie","difficulty":"hard","prompt":"Après trois demi-vies, quelle fraction d’un isotope radioactif père reste-t-il dans un système fermé ?","options":["1/8 de la quantité initiale","1/3 de la quantité initiale","3/4 de la quantité initiale","Aucun atome père"],"correctAnswers":[0],"explanation":"La quantité d’isotope père est divisée par deux à chaque demi-vie. Après trois demi-vies, la fraction restante vaut (1/2)³, soit 12,5 % de la quantité initiale.","image":null,"status":"published"},{"chapterId":"ecologie","difficulty":"easy","prompt":"Que comprend un écosystème ?","options":["Un milieu et les êtres vivants qui y interagissent","Uniquement les animaux d’un territoire","Uniquement les facteurs physiques","Une seule espèce sans environnement"],"correctAnswers":[0],"explanation":"Un écosystème associe une communauté d’organismes à son milieu physicochimique et à leurs interactions. Des flux d’énergie et des transferts de matière relient ces différentes composantes.","image":null,"status":"published"},{"chapterId":"ecologie","difficulty":"medium","prompt":"Quels organismes peuvent être des producteurs primaires ?","options":["Une plante chlorophyllienne","Une cyanobactérie photosynthétique","Une bactérie chimioautotrophe","Un animal strictement hétérotrophe"],"correctAnswers":[0,1,2],"explanation":"Les producteurs primaires fabriquent de la matière organique à partir de carbone minéral. Ils utilisent une source d’énergie lumineuse ou, chez certains microorganismes, l’énergie de réactions chimiques.","image":null,"status":"published"},{"chapterId":"ecologie","difficulty":"easy","prompt":"Que désigne la richesse spécifique d’une communauté ?","options":["Le nombre d’espèces présentes","Le nombre total d’individus uniquement","La masse moyenne d’un individu","Le nombre de chromosomes d’une espèce"],"correctAnswers":[0],"explanation":"La richesse spécifique correspond au nombre d’espèces recensées à une échelle donnée. Elle ne suffit pas à décrire toute la diversité, car l’abondance relative des espèces compte aussi.","image":null,"status":"published"},{"chapterId":"ecologie","difficulty":"medium","prompt":"Dans un modèle logistique simple, que représente la capacité de charge K ?","options":["Un effectif d’équilibre fixé par les conditions du modèle","Un taux de mutation universel","Une durée de génération obligatoirement constante","Le nombre de niveaux trophiques"],"correctAnswers":[0],"explanation":"Dans le modèle logistique, la croissance nette tend vers zéro lorsque l’effectif atteint K. Cette capacité dépend des ressources et des conditions du milieu ; elle n’est donc pas une constante universelle de l’espèce.","image":null,"status":"published"},{"chapterId":"ecologie","difficulty":"hard","prompt":"Quelles affirmations sont exactes à propos de la dérive génétique ?","options":["Elle correspond à des fluctuations aléatoires des fréquences alléliques","Elle est généralement plus marquée dans les petites populations","Elle favorise nécessairement les allèles les plus avantageux","Elle peut entraîner la fixation d’un allèle neutre"],"correctAnswers":[0,1,3],"explanation":"La dérive résulte du caractère fini de l’échantillonnage des allèles transmis. Elle peut réduire la diversité génétique indépendamment de l’avantage sélectif des allèles.","image":null,"status":"published"},{"chapterId":"ecologie","difficulty":"hard","prompt":"Quelles conditions suffisent au modèle classique de Hardy-Weinberg pour maintenir les fréquences alléliques entre générations ?","options":["Une population de taille théoriquement infinie","L’absence de sélection, de migration et de mutation","Un accouplement aléatoire pour le locus étudié","Une sélection directionnelle intense"],"correctAnswers":[0,1,2],"explanation":"Le modèle de Hardy-Weinberg décrit une situation de référence sans forces évolutives modifiant les fréquences alléliques. La panmixie conduit aux proportions génotypiques p², 2pq et q² pour un locus autosomique à deux allèles.","image":null,"status":"published"},{"chapterId":"ecologie","difficulty":"medium","prompt":"Quelles caractéristiques définissent un mutualisme ?","options":["Les deux partenaires retirent un bénéfice de l’interaction dans le contexte considéré","Un partenaire bénéficie toujours au détriment de l’autre","Il peut être facultatif ou obligatoire selon les systèmes","Il implique nécessairement deux espèces animales"],"correctAnswers":[0,2],"explanation":"Le mutualisme décrit une interaction à effets positifs réciproques sur les partenaires. Ses effets peuvent dépendre du contexte environnemental et il peut concerner des organismes de groupes très différents.","image":null,"status":"published"},{"chapterId":"ecologie","difficulty":"medium","prompt":"Pourquoi la production disponible diminue-t-elle généralement entre niveaux trophiques successifs ?","options":["Une partie de l’énergie est dissipée par la respiration","Toute la biomasse d’un niveau n’est pas consommée ni assimilée","L’énergie se recycle indéfiniment sans perte","La photosynthèse transforme directement toute la chaleur en biomasse"],"correctAnswers":[0,1],"explanation":"Une fraction de l’énergie assimilée est utilisée par le métabolisme et dissipée sous forme de chaleur. De plus, une partie de la matière n’est pas consommée ou assimilée et rejoint notamment les réseaux détritiques.","image":null,"status":"published"},{"chapterId":"ecologie","difficulty":"hard","prompt":"Dans le modèle de compétition de Lotka-Volterra, la compétition interspécifique correspond à…","options":["Un effet négatif de chaque espèce sur la croissance de l’autre","Un bénéfice obligatoire pour les deux espèces","Une prédation où l’une consomme systématiquement l’autre","Une absence de partage de ressources limitantes"],"correctAnswers":[0],"explanation":"La compétition peut résulter de l’exploitation d’une ressource commune limitante ou d’interférences directes. Dans le modèle, les coefficients de compétition traduisent l’effet d’une espèce sur la croissance de l’autre.","image":null,"status":"published"},{"chapterId":"ecologie","difficulty":"easy","prompt":"Quelles actions peuvent améliorer la connectivité écologique d’un paysage fragmenté ?","options":["Maintenir des corridors entre habitats favorables","Restaurer des habitats relais","Rendre toutes les routes infranchissables pour la faune","Supprimer tous les habitats entre deux populations"],"correctAnswers":[0,1],"explanation":"La connectivité permet des déplacements d’individus et peut favoriser les échanges génétiques entre populations. L’efficacité d’un corridor dépend de l’espèce et de la qualité des habitats traversés.","image":null,"status":"published"}]$bank$::jsonb) loop
    if exists(select 1 from public.questions where chapter_id = item->>'chapterId' and prompt = item->>'prompt' and deleted_at is null) then continue; end if;
    insert into public.questions(chapter_id,author_id,difficulty,prompt,options,image_path,status)
    values(item->>'chapterId',owner_id,(item->>'difficulty')::public.question_difficulty,item->>'prompt',
      array(select jsonb_array_elements_text(item->'options')),item->>'image','published')
    returning id into question_id;
    insert into private.question_keys(question_id,correct_answers,explanation)
    values(question_id,array(select value::smallint from jsonb_array_elements_text(item->'correctAnswers')),item->>'explanation');
    inserted_count := inserted_count + 1;
  end loop;
  insert into private.audit_events(actor_id,action,payload)
  values(owner_id,'questions.initial_seed',jsonb_build_object('count',inserted_count));
end;
$seed$;

commit;

